// TH16 v1.00a Stage 1 boss, Boss2 (second nonspell).
// Source: st01bs.ecl.txt:175-229 (entry), deps 231-263 (Boss2_at), 265-316 (Boss2_at2).

const TIME_LIMIT: int = 1624;
const OPENING_BUFFER: int = 120;
// Source Boss2:210 sets the 1500-frame interrupt at entry; the 120-frame startup
// (Boss2:214-217) is inside that window, so the attack itself runs 1380 frames.
// OPENING_BUFFER is a separate training-shell wait, before source t=0.
const ATTACK_FRAMES: int = 1380;

const TH16_RICE: int = 480; // source etSprite(0, 8, 10)
const TH16_BALL: int = 416; // source etSprite(1, 4, 2)

// ---- source moveLimit(0,128,280,96) + moveRand(60,4,1.0) ----
// Inner direction region x +-70, y 104..152; position clamp x[-140,140], y[80,176].
// Shared enemy slots: int 0 = next step index, fx 0/1 = logical unit direction.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

// source 412 moveRand(60,4,1.0): speed 1 - k/60, no reflection at the limit.
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard (epsilon 0.05 rad).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// source Boss2_at (st01bs.ecl.txt:231-263): fixed 90deg fan, 6 lanes x I0=4 layers,
// spread A shrinks by B each 10-frame wave. EX ANIM/SPEEDUP are birth presentation
// (omitted); only the ANIM entry retreat position -= 4*velocity is kept per bullet.
async sub boss_at() {
    var waves: int = 10;
    var speed0: fx = 2.5fx;
    var speed_step: fx = 0.1666667fx; // (3.0 - 2.5) / 3 layers
    if global(GVAR_RANK) == RANK_EASY {
        waves = 7;
        speed0 = 1.5fx;
        speed_step = 0.5fx;           // (3.0 - 1.5) / 3 layers
    }
    var spread: int = 13835;     // source A = 1.3264502 rad = 76deg
    var spread_step: int = 1347; // source B = -0.12915437 rad = -7.4deg
    var base: int = 16384;       // 90deg
    var off: int = 0;
    var speed: fx = 0fx;
    var shift: fx = 0fx;
    var a: angle = 0deg;
    for w in 0..waves {
        for q in 0..4 {
            speed = speed0 + speed_step * q;
            shift = 4fx * speed;
            for i in 0..6 {
                // fan F(N,i), N=6 even: H=(i/2)*delta+delta/2, sign alternates
                off = (i / 2) * spread + spread / 2;
                if i % 2 != 0 { off = -off; }
                a = (base + off) as angle;
                _ = fire(TH16_RICE, 10,
                         $self_x - shift * cos(a),
                         $self_y - shift * sin(a),
                         speed, a, none, none);
            }
        }
        spread = spread - spread_step;
        wait(10);
    }
}

// source Boss2_at2 ACCEL: a=120, r=1/60, s keeps the current bullet angle.
xformdef AT2_ACCEL {
    @120 set_accel(0.0166667fx);
    set_accel(0fx);
}

// source Boss2_at2 (st01bs.ecl.txt:265-316): aimed fan from a random circular
// offset, speed 1.0, ACCEL along the current direction for 120 frames.
async sub boss_at2() {
    var gap: int = 20;
    var ways: int = 1;
    if global(GVAR_RANK) == RANK_HARD { ways = 3; }
    if global(GVAR_RANK) == RANK_LUNATIC { ways = 5; }
    if global(GVAR_RANK) == RANK_EASY { gap = 60; }
    if global(GVAR_RANK) == RANK_HARD { gap = 30; }
    wait(60);
    // source floatTime(0,C,0,1200,start,goal): native frames=0 writes only start.
    var i: int = 0;
    while i < 6000 {
        // source circlePos(%A,%B,%RANDRAD,%RANDF*128); angle first, then radius.
        var th: angle = rand(65536) as angle;
        var rad: fx = ((rand(65536) - 32768) as fx / 65536 + 0.5fx) * 128fx;
        var mx: fx = $self_x + rad * cos(th);
        var my: fx = $self_y + rad * sin(th) * 0.4fx;
        var aim: angle = atan2($player_y - my, $player_x - mx);
        var off: int = 0;
        for j in 0..ways {
            off = ((j + 1) / 2) * 1274; // 7deg
            if j % 2 != 0 { off = -off; }
            var a: angle = aim + (off as angle);
            _ = fire(TH16_BALL, 2,
                     mx - 4fx * cos(a),
                     my - 4fx * sin(a),
                     1fx, a, AT2_ACCEL, none);
        }
        wait(gap);
        i = i + 1;
    }
}

// Source Boss2:175-229 entry runs the second nonspell on the same boss.
async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx); // source setHurtbox(40,40) -> r=20
    set_hitbox(24fx);  // source setHitbox(48,48) -> r=24
    wait(90);         // Boss2:214, within the source's 1500-frame timer
    wait(30);         // Boss2:217; separate from the shell's OPENING_BUFFER
    spawn boss_at2();  // Boss2:219
    var elapsed: int = 0;
    loop {
        spawn boss_at();          // Boss2:222
        wait(120);                // Boss2:223
        elapsed = elapsed + 120;
        if elapsed >= ATTACK_FRAMES { return; } // BossCard2 interrupt at source 1500
        card_move_rand();         // Boss2:224
        card_wait(60);            // Boss2:225
        elapsed = elapsed + 60;
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 9700, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
